 var rp=function(i){var x=pts[i][0],y=pts[i][1],d=pts[i][2];return pt?(x>aw*.55?[x-d/2-50,y+d/2-26]:[x+d/2-6,y-d/2-6]):[x-22,y-d/2-64]};
