/* ---------- moteur de questions (test, bilan) ---------- */
var shuf=function(a){a=a.slice();for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1)),t=a[i];a[i]=a[j];a[j]=t}return a};
var quiz=function(box,qs,o){o=o||{};var i=0,ans=[];var say_=function(t){try{window.say&&window.say(t)}catch(e){}};
 var fin=function(){var dom={};ans.forEach(function(a){var d=dom[a.d]||(dom[a.d]={ok:0,n:0,ko:[]});d.n++;if(a.ok)d.ok++;else d.ko.push(a.k)});
  var ok=ans.filter(function(a){return a.ok}).length,res={ok:ok,n:ans.length,dom:dom,date:Date.now(),key:o.key};
  try{save[(o.key||'t')+'q']=res;persist()}catch(e){}
  var p=P();p.tests=p.tests||{};p.tests[(o.key||'').toUpperCase()]=res;sv();
  if(o.summary!==false){var h='<div class="mrq"><div class="q">Bilan terminé : '+ok+' / '+res.n+'</div>'+Object.keys(dom).map(function(d){var v=Math.round(100*dom[d].ok/dom[d].n),s=stat(v);return '<div style="display:flex;gap:8px;align-items:center;margin:6px 0;font-weight:800;font-size:.9rem"><span style="flex:1;text-align:left">'+esc(d)+'</span><span class="chipst '+s[1]+'" style="font-size:.75rem;padding:2px 10px;border-radius:999px;background:'+(v>=75?'#d9f5e8':v>=50?'#fff1cc':'#ffe1d6')+'">'+dom[d].ok+'/'+dom[d].n+' · '+s[0]+'</span></div>'}).join('')+'<div class="note" style="margin-top:8px">Les résultats sont dans l’Espace parent.</div></div>';box.innerHTML=h}
  if(o.onEnd)o.onEnd(res);};
 var next=function(ok,q){ans.push({d:q.d,k:q.k,ok:ok});i++;draw_()};
 var draw_=function(){var q=qs[i];if(!q){fin();return}
  var h='<div class="mrq"><div style="font-weight:800;font-size:.85rem;color:#5b6491">'+esc(o.title||'Test')+' · question '+(i+1)+' sur '+qs.length+'</div><div class="prgb" style="margin:6px 0 12px"><i style="width:'+(i/qs.length*100)+'%"></i></div><div style="font-weight:800;color:#2459e6;font-size:.9rem">'+esc(q.d)+'</div>'+(q.say?'<button class="audio" id="qa" style="margin:8px 0">🔊 Écouter</button>':'')+'<div class="q">'+esc(q.q)+'</div>';
  if(q.n!=null){h+='<div class="kv" id="kv"></div><div class="kp">'+[1,2,3,4,5,6,7,8,9,'⌫',0,'OK'].map(function(k){return '<button data-k="'+k+'">'+k+'</button>'}).join('')+'</div>'}
  else{var ix=shuf(q.o.map(function(_,j){return j}));h+=ix.map(function(j){return '<button class="opt" data-j="'+j+'">'+esc(q.o[j])+'</button>'}).join('')}
  box.innerHTML=h+'</div>';
  var qa=box.querySelector('#qa');if(qa){qa.onclick=function(){say_(q.say)};setTimeout(function(){say_(q.say)},300)}
  if(q.n!=null){var v='';box.querySelectorAll('[data-k]').forEach(function(b){b.onclick=function(){var k=b.dataset.k;if(k==='⌫')v=v.slice(0,-1);else if(k==='OK'){if(v!=='')next(+v===q.n,q);return}else if(v.length<4)v+=k;box.querySelector('#kv').textContent=v}})}
  else box.querySelectorAll('[data-j]').forEach(function(b){b.onclick=function(){next(+b.dataset.j===q.a,q)}})};
 draw_();};

